import{_ as s,o as e,c as i,ag as t}from"./chunks/framework.DNmTgtHf.js";const g=JSON.parse('{"title":"Graph Databases & GraphQL — Related in Name Only","description":"","frontmatter":{},"headers":[],"relativePath":"databases/graph_and_graphql/GraphDbAndGraphQl.md","filePath":"databases/graph_and_graphql/GraphDbAndGraphQl.md"}'),n={name:"databases/graph_and_graphql/GraphDbAndGraphQl.md"};function r(h,a,p,l,o,d){return e(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="graph-databases-graphql-—-related-in-name-only" tabindex="-1">Graph Databases &amp; GraphQL — Related in Name Only <a class="header-anchor" href="#graph-databases-graphql-—-related-in-name-only" aria-label="Permalink to &quot;Graph Databases &amp; GraphQL — Related in Name Only&quot;">​</a></h1><p><strong>The misconception first:</strong> GraphQL and graph databases are NOT related. GraphQL is an <strong>API technology</strong>; graph databases are a <strong>database category</strong>. The shared word &quot;graph&quot; is a coincidence of naming.</p><h2 id="graph-databases" tabindex="-1">Graph databases <a class="header-anchor" href="#graph-databases" aria-label="Permalink to &quot;Graph databases&quot;">​</a></h2><h3 id="fraud-detection-—-the-canonical-use-case" tabindex="-1">Fraud detection — the canonical use case <a class="header-anchor" href="#fraud-detection-—-the-canonical-use-case" aria-label="Permalink to &quot;Fraud detection — the canonical use case&quot;">​</a></h3><p>Fraud is often about <strong>relationships</strong>, not individual records. Each account looks fine in isolation; the pattern only appears when you connect them:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Alice   → Device D1</span></span>
<span class="line"><span>Bob     → Device D1     ← shared device: suspicious</span></span>
<span class="line"><span>Charlie → Device D1</span></span></code></pre></div><p><strong>Circular money movement:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A → B → C → D → A</span></span></code></pre></div><p>Graph databases can detect cycles like this efficiently.</p><p><strong>Fraud use cases:</strong> shared devices, shared addresses, money-laundering chains, circular transactions, networks of related accounts.</p><p><strong>Interview answer:</strong> graph databases are useful in fraud detection because fraud often involves hidden relationships among accounts, devices, IPs, customers, and transactions — graph traversal makes these patterns easy to discover.</p><h2 id="graphql" tabindex="-1">GraphQL <a class="header-anchor" href="#graphql" aria-label="Permalink to &quot;GraphQL&quot;">​</a></h2><h3 id="what-it-is" tabindex="-1">What it is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to &quot;What it is&quot;">​</a></h3><p>A query language for APIs that lets clients request <strong>exactly the data they need</strong>.</p><p>REST — multiple endpoints:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /users/123</span></span>
<span class="line"><span>GET /users/123/orders</span></span></code></pre></div><p>GraphQL — single request:</p><div class="language-graphql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">graphql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  user</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">123</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    name</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    orders</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">      amount</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="how-the-backend-works-vs-rest-routing" tabindex="-1">How the backend works (vs REST routing) <a class="header-anchor" href="#how-the-backend-works-vs-rest-routing" aria-label="Permalink to &quot;How the backend works (vs REST routing)&quot;">​</a></h3><p>In REST, the URL routes to a controller. GraphQL instead exposes <strong>one endpoint</strong> — <code>POST /graphql</code> — and routes by query shape:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>REST:     URL  → Controller</span></span>
<span class="line"><span>GraphQL:  Query → Schema → Resolvers</span></span></code></pre></div><p><strong>Schema</strong> declares what&#39;s queryable:</p><div class="language-graphql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">graphql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Query</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  user</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ID</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">): </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">User</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><strong>Resolver</strong> is the function that fetches it:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">user</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">_</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">args</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> userRepository.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">findById</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(args.id);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>A frontend query for <code>user(id:123){ name }</code> invokes the <code>user</code> resolver.</p><h3 id="aggregating-multiple-services" tabindex="-1">Aggregating multiple services <a class="header-anchor" href="#aggregating-multiple-services" aria-label="Permalink to &quot;Aggregating multiple services&quot;">​</a></h3><p>A GraphQL server can call the User Service, Order Service, and Payment Service, combine the results, and return one response — it&#39;s an aggregation layer.</p><h3 id="graphql-and-n-1" tabindex="-1">GraphQL and N+1 <a class="header-anchor" href="#graphql-and-n-1" aria-label="Permalink to &quot;GraphQL and N+1&quot;">​</a></h3><p>Classic problem. For:</p><div class="language-graphql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">graphql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">  users</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    name</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">    orders</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">amount</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>a naive implementation does <em>get users, then for each user get orders</em> — N+1 again. <strong>Common solution: DataLoader</strong>, which batches the per-user requests into one <code>WHERE user_id IN (...)</code> query. (General N+1 mechanics: <code>spring/jpa_lazy_eager/LazyEagerN1.md</code>.)</p><h3 id="the-mental-model" tabindex="-1">The mental model <a class="header-anchor" href="#the-mental-model" aria-label="Permalink to &quot;The mental model&quot;">​</a></h3><p>The GraphQL server is simply a backend component. Instead of writing many REST endpoints (<code>GET /user</code>, <code>GET /orders</code>), you write resolvers. GraphQL parses the request, figures out which fields were requested, invokes the appropriate resolvers, fetches the data, and returns exactly the requested structure.</p><h2 id="gotchas-trick-questions" tabindex="-1">Gotchas / Trick questions <a class="header-anchor" href="#gotchas-trick-questions" aria-label="Permalink to &quot;Gotchas / Trick questions&quot;">​</a></h2><ol><li><strong>&quot;GraphQL must use a graph database.&quot;</strong> No — GraphQL is an API query language; it can sit on top of SQL, NoSQL, other services, anything. Graph databases (Neo4j, Neptune) are a storage category.</li><li><strong>&quot;GraphQL eliminates the N+1 problem.&quot;</strong> The opposite — naive resolvers <em>reintroduce</em> it (one query per nested field per parent). DataLoader-style batching is the standard fix.</li><li><strong>&quot;How does GraphQL route without URLs?&quot;</strong> Single <code>POST /graphql</code> endpoint; the query body is parsed against the schema and dispatched to resolvers — query shape replaces URL routing.</li></ol><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><p><strong>Q. GraphQL vs graph database?</strong> A. GraphQL is an API query language; a graph database is a database category. Unrelated despite the name.</p><p><strong>Q. Why are graph databases good for fraud detection?</strong> A. Fraud lives in hidden relationships (shared devices/addresses, circular transfers) — graph traversal finds these patterns efficiently.</p><p><strong>Q. How does a GraphQL backend know what to execute?</strong> A. One <code>POST /graphql</code> endpoint; the query is validated against the schema and each requested field is resolved by its resolver function.</p><p><strong>Q. How does N+1 appear in GraphQL, and what&#39;s the fix?</strong> A. Naive nested resolvers fire one query per parent entity; DataLoader batches them into <code>WHERE id IN (...)</code> queries.</p><p><strong>Q. What can a GraphQL server sit in front of?</strong> A. Anything — databases, REST services, multiple microservices — aggregating results into one response shaped exactly like the query.</p>`,42)])])}const k=s(n,[["render",r]]);export{g as __pageData,k as default};
